// Valores de fabrica do veiculo `id`. Devolve false se o id nao estiver na tabela.
inline bool FactoryUpgrades(uint32_t id, uint32_t* page35, uint32_t* page37) {
    for (const VehicleUpgrade& entry : kVehicleUpgrades) {
        if (entry.id == id) {
            if (page35) *page35 = entry.page35;
            if (page37) *page37 = entry.page37;
            return true;
        }
    }
    return false;
}

